operation.add:
// BPOS
if ($this->user->hasPermission('access', 'extension/module/bpos')) {
    $hpwd[] = array(
        'name'     => 'Barik POS',
        'href'     => $this->url->link('extension/module/bpos', 'user_token=' . $this->session->data['user_token'], true),
        'children' => array()
    );
}
// BPOS

// BPOS
if ($this->user->hasPermission('access', 'extension/module/bpos')) {
	$data['menus'][] = array(
		'id'       => 'menu-bpos',
		'icon'     => 'fa-shopping-cart',
		'name'     => 'Barik POS',
		'href'     => $this->url->link('extension/module/bpos', 'user_token=' . $this->session->data['user_token'], true),
		'children' => array()
	);
}
// BPOS

// BPOS
$data['pos_menu'] = $this->user->hasPermission('access', 'extension/module/bpos');

if ($data['pos_menu']) {
	// Same address as the sign-in page in the BPOS settings: the saved slug, if its SEO URL exists
	$bpos_slug = (string)$this->config->get('module_bpos_slug');
	$bpos_seo = $bpos_slug === '' ? false : $this->db->query("SELECT `keyword` FROM `" . DB_PREFIX . "seo_url` WHERE `query` = 'bpos/auth' AND `store_id` = '0' AND `keyword` = '" . $this->db->escape($bpos_slug) . "' LIMIT 1");

	$data['pos_frontend'] = rtrim(HTTPS_CATALOG, '/') . '/' . ($bpos_seo && $bpos_seo->num_rows ? $bpos_slug : 'index.php?route=bpos/auth');
	$data['pos_setting'] = $this->url->link('extension/module/bpos', 'user_token=' . $this->session->data['user_token'], true);
}
// BPOS
